mapper.select:
select a.`project_id`,b.`project_name`,a.`id`,a.`instance_name`,a.`path`,a.`create_time`,a.`update_time`,a.`status` from `instance_manage` a inner join `project_manage` b on a.`project_id`=b.`id`
b.`project_name` like concat('%',#{param.projectName},'%')
and a.`status` = #{param.status}
